 static T Field<T>(object obj,string name){return (T)obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
 static void Call(object obj,string name){obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,null);}
 static void Pump(int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(8);}}
 static void Wait(Func<bool> condition,string stage){var end=DateTime.UtcNow.AddSeconds(20);while(!condition()&&DateTime.UtcNow<end)Pump(20);if(!condition())throw new Exception("Timed out: "+stage);}
 static void Check(string name,bool pass){checks.Add(new{name,pass});if(!pass)throw new Exception(name);}
 static void Dialogs(){EnumThreadWindows(GetCurrentThreadId(),delegate(IntPtr hwnd,IntPtr value){string title=Title(hwnd);if(title.StartsWith("Export ")){if(dialogMode=="cancel")SendMessage(hwnd,0x0010,IntPtr.Zero,IntPtr.Zero);else{IntPtr edit=GetFocus();string text=Title(edit);if(text.EndsWith(".json",StringComparison.OrdinalIgnoreCase)){SendMessage(edit,0x000C,IntPtr.Zero,filename);SendMessage(hwnd,0x0111,(IntPtr)1,IntPtr.Zero);}}}else if(title=="Optional glossary export")SendMessage(hwnd,0x0111,(IntPtr)7,IntPtr.Zero);return true;},IntPtr.Zero);}
 static void ClickMenu(LocalTranslationEditor editor,string method,int index){Call(editor,method);Pump(15);ContextMenuStrip menu=null;EnumThreadWindows(GetCurrentThreadId(),delegate(IntPtr hwnd,IntPtr value){var control=Control.FromHandle(hwnd) as ContextMenuStrip;if(control!=null&&control.Visible)menu=control;return true;},IntPtr.Zero);if(menu==null)throw new Exception("Actual popup not found");var bounds=menu.Items[index].Bounds;IntPtr point=(IntPtr)(((bounds.Top+bounds.Height/2)<<16)|(bounds.Left+bounds.Width/2));SendMessage(menu.Handle,0x0201,(IntPtr)1,point);SendMessage(menu.Handle,0x0202,IntPtr.Zero,point);Pump(30);}
