 static int Run(string[] args){try{typeof(Store).GetField("Home").SetValue(null,Path.GetFullPath(args[2]));typeof(LocalTranslation).GetField("Home").SetValue(null,Path.Combine(output,"Home"));var run=LocalTranslation.Runs(null).Single();var cover=EnglishSupport.CoveredLocalSources(run.Root);string source="物品",key=LocalLibrary.Key(cover[source],source);string journalHash=Store.Hash(LocalTranslation.RunFile(run.Id,"results.jsonl"));LocalTranslation.Edit(run.Id,new LocalEdit{Key=key,Source=source,Category=cover[source],Context="EnglishCoverage",Target="Objets (test)"});var settings=LocalTranslation.Options(run);string optionsHash=Store.Hash(LocalTranslation.RunFile(run.Id,"options.json"));
