  for(int mask=0;mask<16;mask++){for(int i=0;i<4;i++)filters[origins[i]].Checked=(mask&(1<<i))!=0;Pump(10);int count=all.Count(x=>(mask&2)!=0&&data.Model.ContainsKey(x.Source)||(mask&4)!=0&&authored.Contains(x.Source)||(mask&8)!=0&&imported.Contains(x.Source)||(mask&1)!=0&&!data.Model.ContainsKey(x.Source)&&!authored.Contains(x.Source)&&!imported.Contains(x.Source));Check("origin combination "+mask,grid.RowCount==count);}
  foreach(var filter in filters.Values)filter.Checked=true;var search=Field<TextBox>(form,"search");search.Text=source;Pump(350);var shown=Field<List<LocalUnit>>(form,"shown");int row=shown.FindIndex(x=>x.Source==source);grid.CurrentCell=grid.Rows[row].Cells[1];grid.ClearSelection();grid.Rows[row].Selected=true;Pump(20);Check("typed correction visible and source selection stable",Field<TextBox>(form,"target").Text=="Objets (test)"&&Field<HashSet<string>>(form,"selected").Count==1);
  search.Text="媚药";Pump(350);Check("filter retains hidden selection",Field<HashSet<string>>(form,"selected").Contains(source));search.Text=source;Pump(350);shown=Field<List<LocalUnit>>(form,"shown");row=shown.FindIndex(x=>x.Source==source);grid.CurrentCell=grid.Rows[row].Cells[1];grid.ClearSelection();grid.Rows[row].Selected=true;Pump(20);
  var automation=new System.Windows.Forms.Timer{Interval=70};automation.Tick+=delegate{Dialogs();};automation.Start();dialogMode="cancel";for(int i=0;i<8;i++)ClickMenu(form,"ExportMenu",i%2);Check("actual export cancel/reopen has no disposed popup",errors.Count==0);
  dialogMode="save";filename=Path.Combine(output,"selected-export.json");ClickMenu(form,"ExportMenu",0);Wait(()=>File.Exists(filename)&&!Field<bool>(form,"busy"),"selected export");var pack=LocalTranslation.Read<LocalDictionaryPack>(filename);Check("actual selected export preserves exact source and correction",pack.Entries.Count==1&&pack.Entries[0].Source==source&&pack.Entries[0].Target=="Objets (test)");
  filename=Path.Combine(output,"filtered-export.json");ClickMenu(form,"ExportMenu",1);Wait(()=>File.Exists(filename)&&!Field<bool>(form,"busy"),"filtered export");pack=LocalTranslation.Read<LocalDictionaryPack>(filename);Check("actual filtered export contains only filtered valid targets",pack.Entries.All(x=>x.Source.Contains(source))&&pack.Entries.Any(x=>x.Source==source));automation.Stop();automation.Dispose();
  for(int i=0;i<12;i++)ClickMenu(form,"BulkMenu",0);Check("selection popup clear/reopen has no disposed popup",errors.Count==0);
  var scales=new List<object>();foreach(float factor in new[]{1f,1.25f,1.5f}){form.Font=new Font("Segoe UI",10*factor);form.ClientSize=new Size(1000,650);Pump(80);Check("text fits at font scale "+factor,filters.Values.All(c=>c.ClientSize.Width>=TextRenderer.MeasureText(c.Text,c.Font,Size.Empty,TextFormatFlags.SingleLine|TextFormatFlags.NoPadding).Width+c.Padding.Horizontal+6));Check("layout fits at font scale "+factor,form.Controls.Cast<Control>().Where(x=>x.Visible).All(x=>x.Right<=form.ClientSize.Width+1&&x.Bottom<=form.ClientSize.Height+1)&&grid.Bottom<=Field<TextBox>(form,"native").Top);scales.Add(new{factor,simulatedFontScale=true});if(factor==1.5f){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,form.Width,form.Height));bitmap.Save(Path.Combine(output,"scaled-after.png"));}}}
  form.Font=new Font("Segoe UI",10);form.ClientSize=new Size(1160,760);Pump(80);var tools=Field<FlowLayoutPanel>(form,"tools");var chips=form.Controls.OfType<FlowLayoutPanel>().Single(x=>x!=tools);using(var picture=new Bitmap(form.ClientSize.Width,chips.Bottom-tools.Top+6)){using(var canvas=Graphics.FromImage(picture))canvas.Clear(form.BackColor);tools.DrawToBitmap(picture,new Rectangle(tools.Left,0,tools.Width,tools.Height));chips.DrawToBitmap(picture,new Rectangle(chips.Left,chips.Top-tools.Top,chips.Width,chips.Height));picture.Save(Path.Combine(output,"controls-after.png"));}
