  data=Field<LocalComparison>(form,"data");var oldLayer=LocalLibrary.Layer(data,"pack:diagnostic-pack");string prior=oldLayer[source],packFile=Path.Combine(LocalLibrary.Home,"Packs",run.Family,"fr","diagnostic-pack.json");File.Copy(packFile,packFile+".before-edit");var editedPack=LocalTranslation.Read<LocalDictionaryPack>(packFile);editedPack.Entries.Single(x=>x.Source==source).Target="Articles (test)";LocalTranslation.Write(packFile,editedPack);Call(form,"Reload");Wait(()=>!Field<bool>(form,"busy")&&!Object.ReferenceEquals(data,Field<LocalComparison>(form,"data")),"pack revision reload");var fresh=Field<LocalComparison>(form,"data");Check("changed pack rebuilds its lookup on refresh",LocalLibrary.Layer(fresh,"pack:diagnostic-pack")[source]=="Articles (test)"&&oldLayer[source]==prior);
