 LocalTranslation.Write(Path.Combine(output,"acceptance.json"),new{status="PASS",checks,errors,actualMenuClicks=22,exportFiles=2,fontScaleChecks=new[]{1,1.25,1.5},physicalMultiMonitorDpiTested=false});Console.WriteLine("PASS: "+checks.Count+" editor checks; actual menu cancellation/export/reopen; scaled labels; no unhandled errors");return 0;
 }catch(Exception e){LocalTranslation.Write(Path.Combine(output,"acceptance.json"),new{status="FAIL",checks,errors,error=e.ToString()});Console.Error.WriteLine(e);return 1;}}
